class Solution {
    public int minSteps(int n) {
        int result = 0;
        for (int d = 2; d * d <= n; d++) {
            while (n % d == 0) {
                result += d;
                n /= d;
            }
        }
        if (n > 1) result += n;
        return result;
    }
}

class Solution {
    public int minSteps(int n) {
        int[] dp = new int[n + 1];
        for (int i = 2; i <= n; i++) {
            dp[i] = i;
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    dp[i] = Math.min(dp[i], dp[i / j] + j);
                }
            }
        }
        return dp[n];
    }
}
